import { blankTerm } from "./cloze";
import type { Card, CardKind, ItemProgress, Pack, Progress, Settings, Word } from "./types";

const MINUTE = 60_000;
const DAY = 24 * 60 * MINUTE;

/**
 * Short-term steps walked while an item is still `learning`. Graduating to `review`
 * takes one correct answer per step, so a word has to survive three separate waits
 * before it starts costing calendar days.
 */
export const LEARNING_STEPS = [1 * MINUTE, 10 * MINUTE, 60 * MINUTE];

/** Days until the next review, indexed by Leitner box. Box 0 is unused. */
export const REVIEW_DAYS = [0, 1, 3, 7, 16, 35];

export const MAX_BOX = 5;

/**
 * The teaching ramp: a word is shown before it is ever asked, recognised before it
 * has to be produced, and only typed out once it is genuinely familiar.
 */
/**
 * What to ask at a given box, and whether the word can carry a sentence.
 *
 * A cloze sits between recognising a word and producing it cold: the sentence
 * gives you the grammar and the company the word keeps, which is most of what
 * "knowing" it means, and it is the first time the word is asked for in context
 * rather than in isolation. Words without an example sentence skip straight on.
 */
export function cardKindForBox(box: number, hasExample = false): CardKind {
  if (box <= 2) return "recognize";
  if (box === 3) return "reverse";
  if (box === 4) return hasExample ? "cloze" : "reverse";
  return "recall";
}

export function emptyProgress(lang: string): Progress {
  return {
    version: 1,
    lang,
    items: {},
    streak: 0,
    bestStreak: 0,
    totalAnswered: 0,
    totalCorrect: 0,
    introducedByDay: {},
  };
}

export function dayKey(now: number): string {
  const d = new Date(now);
  const pad = (n: number) => String(n).padStart(2, "0");
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
}

/** Deterministic PRNG so a seeded run always produces the same quiz. */
export function makeRng(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export function shuffle<T>(items: T[], rng: () => number): T[] {
  const out = items.slice();
  for (let i = out.length - 1; i > 0; i--) {
    const j = Math.floor(rng() * (i + 1));
    const a = out[i] as T;
    const b = out[j] as T;
    out[i] = b;
    out[j] = a;
  }
  return out;
}

function countLearning(progress: Progress): number {
  return Object.values(progress.items).filter((i) => i.stage === "learning").length;
}

/**
 * Decide what to show next.
 *
 * Order of preference: anything already due (most overdue first, weakest first on a
 * tie), then a brand-new word if both the learning-queue and daily caps allow it.
 * Returns null when the user is genuinely caught up.
 */
export function selectNext(
  pack: Pack,
  progress: Progress,
  settings: Settings,
  now: number,
): { word: Word; item: ItemProgress | null } | null {
  const due = Object.values(progress.items)
    .filter((item) => item.due <= now)
    .sort((a, b) => a.due - b.due || a.box - b.box || a.id.localeCompare(b.id));

  const byId = new Map(pack.words.map((w) => [w.id, w] as const));
  for (const item of due) {
    const word = byId.get(item.id);
    // An item whose word vanished (pack trimmed, language switched) is not fatal.
    if (word) return { word, item };
  }

  if (countLearning(progress) >= settings.maxLearning) return null;
  if ((progress.introducedByDay[dayKey(now)] ?? 0) >= settings.newPerDay) return null;

  const next = pack.words.find((w) => !progress.items[w.id]);
  return next ? { word: next, item: null } : null;
}

/** When the next item becomes eligible, or null if there is nothing scheduled. */
/**
 * A skip costs nothing but a delay — punishing it would poison the box levels.
 *
 * A word with no progress row yet gets one in the `new` stage, because without
 * it `selectNext` hands back the very card that was just skipped.
 */
export const SKIP_DELAY_MS = 10 * MINUTE;

export function deferItem(
  existing: ItemProgress | undefined,
  id: string,
  now: number,
): ItemProgress {
  if (existing) return { ...existing, due: now + SKIP_DELAY_MS };
  return {
    id,
    stage: "new",
    box: 0,
    step: 0,
    due: now + SKIP_DELAY_MS,
    lastSeen: 0,
    seen: 0,
    correct: 0,
    lapses: 0,
  };
}

export function nextDueAt(progress: Progress): number | null {
  const times = Object.values(progress.items).map((i) => i.due);
  return times.length ? Math.min(...times) : null;
}

function pickDistractors(pack: Pack, word: Word, rng: () => number, count: number): Word[] {
  const isCandidate = (w: Word) => w.id !== word.id && w.gloss !== word.gloss && w.term !== word.term;
  // Nearby-rank words of the same part of speech make the hardest, fairest choices;
  // widen the net only as far as needed to fill the row.
  const tiers = [
    pack.words.filter((w) => isCandidate(w) && w.pos === word.pos && Math.abs(w.rank - word.rank) <= 60),
    pack.words.filter((w) => isCandidate(w) && w.pos === word.pos),
    pack.words.filter(isCandidate),
  ];

  const picked: Word[] = [];
  const used = new Set<string>();
  for (const tier of tiers) {
    for (const candidate of shuffle(tier, rng)) {
      if (picked.length >= count) break;
      if (used.has(candidate.id)) continue;
      used.add(candidate.id);
      picked.push(candidate);
    }
    if (picked.length >= count) break;
  }
  return picked;
}

/** Strip case, accents, and surrounding punctuation so "Qué" matches "que". */
export function normalize(text: string): string {
  return text
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .replace(/[^\p{L}\p{N}\s'-]/gu, "")
    .trim()
    .replace(/\s+/g, " ");
}

export function buildCard(pack: Pack, word: Word, item: ItemProgress | null, rng: () => number): Card {
  const kind: CardKind =
    item === null || item.stage === "new"
      ? "teach"
      : cardKindForBox(item.box, Boolean(word.example));

  if (kind === "teach") {
    return { kind, word, prompt: word.term, choices: [], answerIndex: -1, accepted: [word.term] };
  }

  if (kind === "recall") {
    return {
      kind,
      word,
      prompt: word.gloss,
      choices: [],
      answerIndex: -1,
      accepted: [word.term, ...word.term.split(/\s*,\s*/)],
    };
  }

  const distractors = pickDistractors(pack, word, rng, 3);
  const label = (w: Word) => (kind === "recognize" ? w.gloss : w.term);
  if (kind === "cloze" && word.example) {
    const blanked = blankTerm(word.example.text, word.term);
    const options = shuffle([word, ...distractors], rng);
    return {
      kind,
      word,
      prompt: blanked,
      choices: options.map((w) => w.term),
      answerIndex: options.findIndex((w) => w.id === word.id),
      accepted: [word.term],
    };
  }
  const options = shuffle([word, ...distractors], rng);
  return {
    kind,
    word,
    prompt: kind === "recognize" ? word.term : word.gloss,
    choices: options.map(label),
    answerIndex: options.findIndex((w) => w.id === word.id),
    accepted: [label(word)],
  };
}

export function isCorrect(card: Card, response: { choice?: number; text?: string }): boolean {
  if (card.kind === "teach") return true;
  const typed = normalize(response.text ?? "");
  if (card.choices.length) {
    // A picked option is the answer, whatever else came along with it. Letting
    // the text win here threw away a correct `--choice` whenever both were
    // passed — box demoted, lapse recorded, streak gone, for the right answer.
    if (response.choice !== undefined) return response.choice === card.answerIndex;
    // Someone who types the right answer instead of its number has got it right.
    if (typed.length > 0) {
      const right = card.choices[card.answerIndex];
      return (
        (right !== undefined && normalize(right) === typed) ||
        card.accepted.some((a) => normalize(a) === typed)
      );
    }
    return false;
  }
  return typed.length > 0 && card.accepted.some((a) => normalize(a) === typed);
}

function freshItem(id: string, now: number): ItemProgress {
  return { id, stage: "new", box: 0, step: 0, due: now, lastSeen: 0, seen: 0, correct: 0, lapses: 0 };
}

/**
 * Fold one answer into progress. Returns a new object; the caller owns persistence.
 *
 * A wrong answer never destroys history — it drops the item one box and sends it back
 * through the short learning steps, which is what makes the box level meaningful.
 */
export function applyAnswer(
  progress: Progress,
  word: Word,
  card: Card,
  correct: boolean,
  now: number,
): Progress {
  const items = { ...progress.items };
  const previous = items[word.id] ?? freshItem(word.id, now);
  const item: ItemProgress = { ...previous, lastSeen: now };
  const introducedByDay = { ...progress.introducedByDay };

  if (card.kind === "teach") {
    const key = dayKey(now);
    introducedByDay[key] = (introducedByDay[key] ?? 0) + 1;
    // Only today's count is ever read; keeping every day since install would grow
    // the progress file by one key a day for the life of the deck.
    for (const day of Object.keys(introducedByDay)) {
      if (day !== key) delete introducedByDay[day];
    }
    item.stage = "learning";
    item.box = 1;
    item.step = 0;
    item.due = now + (LEARNING_STEPS[0] as number);
    items[word.id] = item;
    // A teach card is an introduction, not a question: it must not move the streak
    // or the accuracy numbers.
    return { ...progress, items, introducedByDay };
  }

  item.seen += 1;
  if (correct) item.correct += 1;

  if (correct) {
    if (item.stage === "learning") {
      const step = item.step + 1;
      if (step < LEARNING_STEPS.length) {
        item.step = step;
        item.due = now + (LEARNING_STEPS[step] as number);
      } else {
        item.stage = "review";
        item.step = 0;
        item.box = Math.min(MAX_BOX, item.box + 1);
        item.due = now + (REVIEW_DAYS[item.box] as number) * DAY;
      }
    } else {
      item.box = Math.min(MAX_BOX, item.box + 1);
      item.due = now + (REVIEW_DAYS[item.box] as number) * DAY;
    }
  } else {
    if (item.stage === "review") item.lapses += 1;
    item.stage = "learning";
    item.box = Math.max(1, item.box - 1);
    item.step = 0;
    item.due = now + (LEARNING_STEPS[0] as number);
  }

  items[word.id] = item;
  const streak = correct ? progress.streak + 1 : 0;
  return {
    ...progress,
    items,
    introducedByDay,
    streak,
    bestStreak: Math.max(progress.bestStreak, streak),
    totalAnswered: progress.totalAnswered + 1,
    totalCorrect: progress.totalCorrect + (correct ? 1 : 0),
  };
}

export interface Stats {
  learned: number;
  total: number;
  learning: number;
  review: number;
  mastered: number;
  due: number;
  streak: number;
  bestStreak: number;
  accuracy: number;
}

export function stats(pack: Pack, progress: Progress, now: number): Stats {
  const items = Object.values(progress.items);
  return {
    learned: items.length,
    total: pack.words.length,
    learning: items.filter((i) => i.stage === "learning").length,
    review: items.filter((i) => i.stage === "review").length,
    mastered: items.filter((i) => i.box >= MAX_BOX).length,
    due: items.filter((i) => i.due <= now).length,
    streak: progress.streak,
    bestStreak: progress.bestStreak,
    accuracy: progress.totalAnswered ? progress.totalCorrect / progress.totalAnswered : 0,
  };
}

files.hooks/ticker.ts:
/**
 * The idle drill: a word, a pause, its meaning, the next word.
 *
 * With nothing due and no turn running there is nothing to quiz, but there is
 * still a band. So it tickers: it walks the language's frequency list in order,
 * shows a word alone for a moment, then reveals the gloss. Trying and then
 * seeing is most of what makes a word stick, and it is the whole of what a
 * surface can offer when it has no question to ask.
 *
 * Nothing here is graded and nothing is written. The quiz is elsewhere.
 *
 * It is a pure function of the clock: a render hook is called afresh on every
 * draw and may be called
 * twice for one moment (a resize, another plugin's invalidate), so a ticker
 * that advanced itself per call would jump about. Given the same millisecond
 * this returns the same frame.
 */

import { HIDDEN_FRACTION, TICK_MS } from './names'
import type { Pack, Progress, Word } from './types'

export interface Tick {
  word: Word | null
  /** True once the meaning is showing. */
  revealed: boolean
  learned: number
  total: number
  /** Where this word sits in the frequency list: #1 is the commonest. */
  rank: number
}

export function tickAt(pack: Pack, progress: Progress, now: number): Tick {
  const words = pack.words
  // `now` is wall-clock in practice, but a non-finite or negative value must
  // not index off the end of the list.
  const slot = Number.isFinite(now) ? Math.abs(Math.floor(now / TICK_MS)) : 0
  const index = words.length ? slot % words.length : 0
  const word = words[index] ?? null

  return {
    word,
    revealed: Number.isFinite(now) && (Math.abs(now) % TICK_MS) / TICK_MS >= HIDDEN_FRACTION,
    learned: Object.keys(progress.items).length,
    total: words.length,
    rank: word ? index + 1 : 0,
  }
}

/** A ten-cell progress bar. */
export function bar(fraction: number, cells: number): string {
  const safe = Number.isFinite(fraction) ? fraction : 0
  const filled = Math.max(0, Math.min(cells, Math.round(safe * cells)))

  return '█'.repeat(filled) + '░'.repeat(cells - filled)
}

files.hooks/ui/tiers.ts:
/**
 * Where you are, in words rather than numbers.
 *
 * A count alone — "83 words" — says nothing about whether that is a lot. These
 * thresholds are the honest shape of learning a language's frequency list: the
 * first hundred words are most of what you hear in a day, the first thousand is
 * most of a conversation, and the gaps get wider because the words get rarer.
 */
export interface Tier {
  name: string;
  /** Words needed to have reached it. */
  at: number;
}

export const TIERS: Tier[] = [
  { name: "just arrived", at: 0 },
  { name: "first words", at: 10 },
  { name: "finding your feet", at: 50 },
  { name: "getting by", at: 100 },
  { name: "holding a conversation", at: 250 },
  { name: "comfortable", at: 500 },
  { name: "most of a day's speech", at: 1000 },
];

export interface Standing {
  tier: Tier;
  /** The one above, or null at the top. */
  next: Tier | null;
  /** Words still needed for `next`, or 0 at the top. */
  toGo: number;
  /** How far through the current tier, 0..1. */
  progress: number;
}

export function standing(learned: number): Standing {
  const count = Number.isFinite(learned) ? Math.max(0, Math.floor(learned)) : 0;
  let index = 0;
  for (let i = 0; i < TIERS.length; i++) {
    if (count >= (TIERS[i] as Tier).at) index = i;
  }
  const tier = TIERS[index] as Tier;
  const next = index + 1 < TIERS.length ? (TIERS[index + 1] as Tier) : null;
  if (!next) return { tier, next: null, toGo: 0, progress: 1 };
  const span = next.at - tier.at;
  return {
    tier,
    next,
    toGo: Math.max(0, next.at - count),
    progress: span > 0 ? Math.min(1, (count - tier.at) / span) : 1,
  };
}

files.hooks/types.ts:
/**
 * The shapes the band draws and the store holds.
 *
 * What claudelingo needed when it was a CLI, less everything it no longer has
 * to invent for itself. `AgentStatus` is the whole of what went: it used to
 * reconstruct "is the agent working?" from hook events written to a file and
 * read back, guess a stale `busy` after fifteen minutes, and tail Codex
 * transcripts for the edge Codex gave it no hook for. The band is handed
 * `isWorking` on every draw, so none of that exists.
 */

/** A single vocabulary entry, materialised from the compact pack format. */
export interface Word {
  /** Stable id, e.g. `es:42`. Survives pack edits as long as rank order is stable. */
  id: string
  /** 1-based frequency rank within its pack. */
  rank: number
  /** The word in the target language. */
  term: string
  /** English gloss. May list several senses, comma separated. */
  gloss: string
  /** Coarse part of speech, used to pick plausible distractors. */
  pos: string
  /** A sentence using the word, and its translation. Absent in older packs. */
  example?: { text: string; translation: string }
  /** Optional extra: noun gender, an irregular form, a usage caveat. */
  note?: string
}

export interface Pack {
  /** ISO 639-1 code. */
  code: string
  /** Name in the target language, e.g. "Español". */
  name: string
  /** Name in English, e.g. "Spanish". */
  englishName: string
  words: Word[]
}

/** The compact form a pack is written in: arrays keep it small and diffable. */
export interface RawPack {
  code: string
  name: string
  englishName: string
  /**
   * `[term, gloss, pos, note?, example?]`, ordered most-frequent first.
   *
   * `example` is a short sentence using the word, with its English translation
   * after a `|`. It is what a cloze card blanks out, and it is optional: packs
   * written before sentences existed stay valid.
   */
  words: Array<
    | [string, string, string]
    | [string, string, string, string]
    | [string, string, string, string, string]
  >
}

/** Where an item sits in the teach -> recognise -> produce progression. */
export type Stage = 'new' | 'learning' | 'review'

/** What we are about to ask. `teach` is a no-fail introduction, not a question. */
export type CardKind = 'teach' | 'recognize' | 'reverse' | 'recall' | 'cloze'

export interface ItemProgress {
  /** Word id. */
  id: string
  stage: Stage
  /** Leitner box, 0-5. Drives which card kind is used and the review interval. */
  box: number
  /** Index into LEARNING_STEPS while `stage === "learning"`. */
  step: number
  /** Epoch ms when this item next becomes eligible. */
  due: number
  /** Epoch ms of the last answer, or 0 if never answered. */
  lastSeen: number
  seen: number
  correct: number
  lapses: number
}

export interface Progress {
  version: 1
  lang: string
  items: Record<string, ItemProgress>
  /** Consecutive correct answers, across sessions. */
  streak: number
  bestStreak: number
  totalAnswered: number
  totalCorrect: number
  /** `YYYY-MM-DD` (local) -> words introduced that day, for the new-word cap. */
  introducedByDay: Record<string, number>
}

export interface Card {
  kind: CardKind
  word: Word
  /** Text shown as the question. */
  prompt: string
  /** Choice labels for `recognize` / `reverse` / `cloze`. Empty otherwise. */
  choices: string[]
  /** Index into `choices` of the correct answer, or -1 when there are none. */
  answerIndex: number
  /** Accepted literal answers for `recall`. */
  accepted: string[]
}

export interface Settings {
  /** ISO 639-1 code of the language being studied, or "" before the first pick. */
  lang: string
  /** Max items allowed in `learning` at once. Keeps the queue from flooding. */
  maxLearning: number
  /** Max brand-new words introduced per calendar day. */
  newPerDay: number
  /** Quiz even when no turn is running. */
  alwaysOn: boolean
  /** Ask $.model for memory hooks. */
  enrich: boolean
  /** Model used for memory hooks and pack generation. */
  model: string
  /** Draw the band at all. `/lingo off` clears it without uninstalling. */
  on: boolean
}

/**
 * What the band is showing, between draws.
 *
 * A render hook is called afresh each time and must be able to draw the whole
 * picture from state it kept itself, so this is the band's memory: the card on
 * screen, the answer just given, and whether the person asked to practise while
 * Claude is idle.
 */
export interface BandState {
  /** The card on screen, or null when the band is drilling or caught up. */
  card: Card | null
  /**
   * The answer just given, held for one card so the band can say how it went.
   *
   * Cleared by the press that moves on, so "correct" never outlives the card it
   * describes.
   */
  verdict: Verdict | null
  /** Practise pressed: quiz on regardless of whether a turn is running. */
  practising: boolean
  /** The quiz you asked for, running or just finished. */
  quiz: QuizRun | null
  /** A memory hook fetched for the card on screen. */
  hook: string | null
  /** A fetch in flight, so the band draws a wait rather than firing twice. */
  fetchingHook: boolean
  /** What the person has typed into a `recall` card's field. */
  typed: string
}

/**
 * A quiz you asked for: a bounded run of cards, right where you are.
 *
 * The band already puts a card up while Claude is working, which is the point
 * of the thing — but that is the band deciding, and it ends when the turn does.
 * A run is you deciding: it starts on a press, it keeps asking whether or not a
 * turn is in flight, it counts, and it stops with a score rather than trailing
 * off. Those are different enough to be separate state.
 */
export interface QuizRun {
  /** Cards this run will put up. */
  total: number
  /** Cards dealt with so far, introductions included. */
  done: number
  /** Of the ones that could be got wrong, how many were right. */
  correct: number
  /** How many were introductions — shown, not asked, so not scored. */
  taught: number
}

export interface Verdict {
  correct: boolean
  /** The answer, spelled out, for a card that was got wrong. */
  answer: string
  /** The word it was about, so the band can offer a hook for it. */
  word: Word
}

